<template>
  <section class="notes-area" aria-labelledby="notes-heading">
    <div class="notes-head"><div><h2 id="notes-heading">Catatan ({{ notes.length }})</h2><p v-if="saveMessage" class="save-message">{{ saveMessage }}</p></div><AppButton size="small" variant="secondary" @click="openEditor()"><ion-icon :icon="addOutline" /> Tambah Catatan</AppButton></div>
    <div class="notes-toolbar"><div class="notes-search"><ion-icon :icon="searchOutline" /><input v-model="search" placeholder="Cari catatan..." /></div><select v-model="categoryFilter" aria-label="Filter kategori"><option value="all">Semua kategori</option><option v-for="category in categories" :key="category" :value="category">{{ category }}</option></select><select v-model="sortMode" aria-label="Urutkan catatan"><option value="updated">Terbaru</option><option value="created">Terlama</option></select><button type="button" :class="['pin-filter', { active: pinnedOnly }]" @click="pinnedOnly = !pinnedOnly"><ion-icon :icon="pinOutline" /> {{ pinnedOnly ? 'Pinned' : 'Semua' }}</button></div>
    <div v-if="loading" class="notes-state"><ion-spinner name="crescent" /><p>Memuat catatan...</p></div>
    <div v-else-if="errorMessage" class="notes-state" role="alert"><strong>Catatan gagal dimuat</strong><p>Periksa koneksi internet, lalu coba lagi.</p><button type="button" @click="loadNotes">Coba Lagi</button></div>
    <template v-else><div v-if="filteredNotes.length" class="note-list"><article v-for="note in filteredNotes" :key="note.id" :class="['note-card', categoryClass(note.category)]"><div class="note-card-head"><div><ion-icon v-if="note.is_pinned" :icon="pinOutline" class="pin-icon" /><h3>{{ note.title }}</h3></div><button type="button" class="note-menu" :aria-label="`Aksi ${note.title}`" @click="openMenu(note)"><ion-icon :icon="ellipsisVertical" /></button></div><p>{{ note.content }}</p><div class="note-meta"><span>{{ note.category }}</span><time>{{ formatDate(note.updated_at) }}</time></div></article></div><div v-else class="notes-state"><strong>{{ search || categoryFilter !== 'all' ? 'Tidak ada catatan yang ditemukan.' : 'Belum ada catatan' }}</strong><p>Tambahkan informasi penting mengenai customer ini.</p><AppButton size="small" @click="openEditor()">Tambah Catatan</AppButton></div></template>
    <div v-if="editing" class="note-sheet"><form @submit.prevent="saveNote"><div class="sheet-head"><h2>{{ form.id ? 'Edit Catatan' : 'Tambah Catatan' }}</h2><button type="button" aria-label="Tutup" @click="editing = false">×</button></div><label>Judul<input v-model.trim="form.title" maxlength="80" required /></label><label>Isi catatan<textarea v-model.trim="form.content" rows="6" required /></label><label>Kategori<select v-model="form.category"><option v-for="category in categories" :key="category" :value="category">{{ category }}</option></select></label><label class="pin-toggle"><input v-model="form.is_pinned" type="checkbox" /> Pin catatan</label><p v-if="formError" class="form-error">{{ formError }}</p><div class="sheet-actions"><button type="button" @click="editing = false">Batal</button><button type="submit" :disabled="saving">{{ saving ? 'Menyimpan...' : 'Simpan' }}</button></div></form></div>
    <div v-if="menuNote" class="note-popover"><button type="button" @click="openEditor(menuNote)">Edit</button><button type="button" @click="togglePin(menuNote)">{{ menuNote.is_pinned ? 'Unpin' : 'Pin' }}</button><button type="button" @click="showHistory(menuNote)">Lihat Riwayat</button><button type="button" class="danger" @click="deleteNote(menuNote)">Hapus</button></div>
    <div v-if="historyNote" class="history-sheet"><div class="sheet-head"><h2>Riwayat perubahan</h2><button type="button" @click="historyNote = null">×</button></div><p v-if="!historyRows.length" class="notes-muted">Belum ada riwayat.</p><ul v-else><li v-for="row in historyRows" :key="row.id"><strong>{{ row.action }}</strong><time>{{ formatDate(row.created_at) }}</time></li></ul></div>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { IonIcon, IonSpinner } from '@ionic/vue'
import { addOutline, ellipsisVertical, pinOutline, searchOutline } from 'ionicons/icons'
import AppButton from '@/components/ui/AppButton.vue'
import { customerNotesService, type CustomerNote, type NoteCategory } from '@/services/Admin/customerNotesService'
const props = defineProps<{ customerId: number }>()
const categories: NoteCategory[] = ['Follow Up', 'Preferensi Kavling', 'Hasil Pertemuan', 'Informasi Customer', 'Lainnya']
const notes = ref<CustomerNote[]>([]); const loading = ref(true); const saving = ref(false); const errorMessage = ref(''); const formError = ref(''); const saveMessage = ref(''); const search = ref(''); const categoryFilter = ref('all'); const sortMode = ref('updated'); const pinnedOnly = ref(false); const editing = ref(false); const menuNote = ref<CustomerNote | null>(null); const historyNote = ref<CustomerNote | null>(null); const historyRows = ref<any[]>([])
const form = reactive<{ id: string; title: string; content: string; category: NoteCategory; is_pinned: boolean }>({ id: '', title: '', content: '', category: 'Follow Up', is_pinned: false })
const filteredNotes = computed(() => notes.value.filter((note) => (!search.value || `${note.title} ${note.content}`.toLowerCase().includes(search.value.toLowerCase())) && (categoryFilter.value === 'all' || note.category === categoryFilter.value) && (!pinnedOnly.value || note.is_pinned)).sort((a, b) => { if (a.is_pinned !== b.is_pinned) return a.is_pinned ? -1 : 1; const first = sortMode.value === 'created' ? a.created_at : a.updated_at; const second = sortMode.value === 'created' ? b.created_at : b.updated_at; return sortMode.value === 'created' ? first.localeCompare(second) : second.localeCompare(first) }))
async function loadNotes() { loading.value = true; errorMessage.value = ''; try { notes.value = await customerNotesService.list(props.customerId) } catch (error) { errorMessage.value = error instanceof Error ? error.message : 'Catatan gagal dimuat' } finally { loading.value = false } }
function openEditor(note?: CustomerNote) { menuNote.value = null; Object.assign(form, note ? { id: note.id, title: note.title, content: note.content, category: note.category, is_pinned: note.is_pinned } : { id: '', title: '', content: '', category: 'Follow Up', is_pinned: false }); formError.value = ''; editing.value = true }
async function saveNote() { if (!form.title.trim() && !form.content.trim()) { formError.value = 'Judul atau isi catatan wajib diisi.'; return }; saving.value = true; try { if (form.id) { const updated = await customerNotesService.update(form.id, form); notes.value = notes.value.map((note) => note.id === updated.id ? updated : note); saveMessage.value = 'Catatan berhasil diperbarui.' } else { notes.value.unshift(await customerNotesService.create(props.customerId, form)); saveMessage.value = 'Catatan berhasil ditambahkan.' }; editing.value = false; setTimeout(() => { saveMessage.value = '' }, 2500) } catch (error) { formError.value = error instanceof Error ? error.message : 'Catatan belum berhasil disimpan.' } finally { saving.value = false } }
function openMenu(note: CustomerNote) { menuNote.value = menuNote.value?.id === note.id ? null : note }
async function togglePin(note: CustomerNote) { menuNote.value = null; const updated = await customerNotesService.update(note.id, { is_pinned: !note.is_pinned }); notes.value = notes.value.map((item) => item.id === updated.id ? updated : item) }
async function deleteNote(note: CustomerNote) { menuNote.value = null; if (!window.confirm(`Hapus catatan “${note.title}”?`)) return; await customerNotesService.remove(note.id); notes.value = notes.value.filter((item) => item.id !== note.id); saveMessage.value = 'Catatan berhasil dihapus.' }
async function showHistory(note: CustomerNote) { menuNote.value = null; historyNote.value = note; historyRows.value = await customerNotesService.history(note.id) }
function formatDate(value: string) { return new Date(value).toLocaleString('id-ID', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) }
function categoryClass(category: string) { return category.toLowerCase().replaceAll(' ', '-') }
onMounted(loadNotes)
</script>

<style scoped>
.notes-area { padding-top: 14px; }.notes-head,.note-card-head,.sheet-head { display:flex;align-items:center;justify-content:space-between;gap:10px }.notes-head h2 { margin:0;font-size:18px }.save-message { margin:4px 0 0;color:var(--poliland-green);font-size:11px }.notes-toolbar { display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;margin:14px 0 }.notes-search { display:flex;align-items:center;gap:7px;min-height:42px;padding:0 10px;border:1px solid var(--border-default);border-radius:var(--radius-control);background:var(--surface-primary) }.notes-search ion-icon{color:var(--text-secondary)}.notes-search input,.notes-toolbar select { min-width:0;border:0;outline:0;background:transparent;color:var(--text-primary);font:inherit;font-size:12px }.notes-toolbar select { min-height:42px;padding:0 7px;border:1px solid var(--border-default);border-radius:var(--radius-control) }.note-list{display:grid;gap:10px}.note-card{position:relative;padding:13px;border:1px solid var(--border-default);border-radius:var(--radius-card);background:var(--surface-primary)}.note-card.follow-up{background:#FFF8E8;border-color:#F0D995}.note-card.preferensi-kavling{background:#F0F7FF;border-color:#C9DFF6}.note-card.hasil-pertemuan{background:#F1FAF2;border-color:#CBE7CF}.note-card h3{display:inline;margin:0;font-size:14px}.note-card-head>div{display:flex;align-items:center;gap:6px}.pin-icon{color:var(--poliland-gold-text)}.note-card p{margin:8px 0;color:var(--text-secondary);font-size:12px;line-height:1.45}.note-menu{border:0;background:transparent;color:var(--text-secondary);font-size:18px}.note-meta{display:flex;justify-content:space-between;gap:8px;color:var(--text-secondary);font-size:10px}.note-meta span{color:var(--poliland-gold-text);font-weight:var(--font-weight-bold)}.notes-state{display:flex;flex-direction:column;align-items:center;gap:8px;padding:36px 16px;text-align:center;border:1px dashed var(--border-default);border-radius:var(--radius-card);background:var(--surface-primary)}.notes-state p,.notes-muted{margin:0;color:var(--text-secondary);font-size:12px}.notes-state button{min-height:40px;padding:0 14px;border:0;border-radius:var(--radius-control);background:var(--poliland-green);color:#fff;font:inherit;font-weight:var(--font-weight-bold)}.note-sheet,.history-sheet{position:fixed;inset:0;z-index:10001;display:flex;align-items:flex-end;background:rgba(37,37,37,.35)}.note-sheet form,.history-sheet{width:100%;max-height:88vh;overflow:auto;padding:18px 16px calc(112px + env(safe-area-inset-bottom));border-radius:var(--radius-panel) var(--radius-panel) 0 0;background:var(--surface-primary)}.sheet-head h2{margin:0;font-size:18px}.sheet-head button{border:0;background:var(--surface-muted);border-radius:50%;width:34px;height:34px;color:var(--text-secondary);font-size:20px}.note-sheet label{display:grid;gap:5px;margin-top:12px;color:var(--text-secondary);font-size:11px}.note-sheet input,.note-sheet textarea,.note-sheet select{width:100%;padding:10px;border:1px solid var(--border-default);border-radius:var(--radius-control);background:var(--surface-primary);color:var(--text-primary);font:inherit;font-size:13px}.pin-toggle{display:flex!important;grid-template-columns:auto 1fr;align-items:center}.pin-toggle input{width:auto}.sheet-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:18px}.sheet-actions button{min-height:44px;border:1px solid var(--border-default);border-radius:var(--radius-control);background:var(--surface-muted);font:inherit;font-weight:var(--font-weight-bold)}.sheet-actions button[type=submit]{background:var(--poliland-gold);border-color:var(--poliland-gold)}.form-error{color:var(--status-danger);font-size:12px}.note-popover{position:fixed;right:18px;bottom:112px;z-index:10002;display:grid;padding:6px;border:1px solid var(--border-default);border-radius:var(--radius-control);background:var(--surface-primary);box-shadow:0 8px 24px rgba(37,37,37,.15)}.note-popover button{min-width:130px;padding:10px;border:0;background:transparent;text-align:left;font:inherit;font-size:12px}.note-popover .danger{color:var(--status-danger)}.history-sheet ul{display:grid;gap:12px;margin:16px 0;padding-left:18px}.history-sheet li{color:var(--text-primary);font-size:12px}.history-sheet time{display:block;margin-top:3px;color:var(--text-secondary);font-size:11px}
.pin-filter { min-height:42px;padding:0 10px;border:1px solid var(--border-default);border-radius:var(--radius-control);background:var(--surface-primary);color:var(--text-secondary);font:inherit;font-size:11px }.pin-filter.active { border-color:var(--poliland-gold);background:var(--poliland-gold-soft);color:var(--poliland-gold-text-soft) }
</style>
